import React from 'react';

const AdminLoading = ({
  fullScreen = false,
  label = 'Loading...',
  compact = false,
}) => {
  if (compact) {
    return (
      <div className="flex min-h-[200px] flex-col items-center justify-center p-6" role="status" aria-live="polite">
        <div className="relative w-12 h-12 flex items-center justify-center">
          {/* Circular Track */}
          <div className="w-12 h-12 rounded-full border-4 border-blue-100" />
          {/* Circular Spinning Arc */}
          <div className="absolute top-0 left-0 w-12 h-12 rounded-full border-4 border-transparent border-t-[#2563EB] border-r-[#2563EB] animate-spin" />
        </div>
        {label && <p className="mt-3.5 text-xs font-semibold text-slate-500">{label}</p>}
      </div>
    );
  }

  return (
    <div
      className={`${
        fullScreen ? 'fixed inset-0 z-[100]' : 'min-h-[400px]'
      } flex flex-col items-center justify-center bg-[#F8FAFC]/90 p-8`}
      role="status"
      aria-live="polite"
    >
      <div className="flex flex-col items-center justify-center bg-white p-8 rounded-3xl shadow-lg border border-slate-100">
        <div className="relative w-16 h-16 flex items-center justify-center">
          {/* Circular Track */}
          <div className="w-14 h-14 rounded-full border-4 border-blue-100" />
          {/* Circular Spinning Arc */}
          <div className="absolute top-1 left-1 w-14 h-14 rounded-full border-4 border-transparent border-t-[#2563EB] border-r-[#2563EB] animate-spin" />
        </div>
        <p className="mt-4 text-sm font-bold text-slate-800">{label}</p>
        <span className="mt-1 text-xs text-slate-400 font-medium">Please wait...</span>
      </div>
    </div>
  );
};

export default AdminLoading;
